DELETE FROM qna
WHERE QNA_NUM = #{qnaNum}
AND MEM_ID = #{memId}

mapper.select:
SELECT q.QNA_NUM, q.MEM_ID, q.CATE_NUM, q.TITLE, q.CONTENT, q.CREATE_DATE, q.UPDATE_DATE, q.QNA_STATUS, q.ANSWER_CONTENT, q.ANSWER_DATE, q.ADMIN_ID, q.VIEW_COUNT, c.CATE_NAME, m.MEM_NAME FROM qna q LEFT JOIN qna_category c ON q.CATE_NUM = c.CATE_NUM LEFT JOIN member m ON q.MEM_ID = m.MEM_ID
AND q.CATE_NUM = #{cateNum}
AND q.MEM_ID LIKE CONCAT('%', #{memId}, '%')
AND q.QNA_STATUS = #{qnaStatus}
ORDER BY q.CREATE_DATE DESC

